package com.bank.topology.service;
import com.bank.topology.model.Node;
import java.util.*;
import java.util.logging.*;

public class TopologyRouter {
    private static final Logger log = Logger.getLogger(TopologyRouter.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final Node primary;
    private final List<Node> replicas;
    private int rr = 0;
    public TopologyRouter(Node primary, List<Node> replicas) {
        this.primary = primary; this.replicas = replicas;
    }
    // Single-primary: all writes go to the one writable node
    public String routeWrite() {
        log.info(() -> "WRITE -> " + primary.getName());
        return primary.getName();
    }
    // Read replicas: round-robin across replicas
    public String routeRead() {
        Node r = replicas.get(rr++ % replicas.size());
        log.info(() -> "READ -> " + r.getName() + (r.getUpstream() != null ? " (cascaded from " + r.getUpstream() + ")" : ""));
        return r.getName();
    }
    // Why active-active is risky: two concurrent writes to same version conflict
    public boolean detectConflict(long versionA, long versionB) {
        boolean conflict = versionA == versionB;   // both based on same version → clash
        if (conflict) log.severe(() -> "CONFLICT: two primaries wrote version " + versionA + " — needs resolution");
        return conflict;
    }
}
