package com.bank.topology;
import com.bank.topology.model.Node;
import com.bank.topology.service.TopologyRouter;
import java.util.*;
import java.util.logging.*;

public class TopologyDemo {
    public static void main(String[] args) {
        Node primary = new Node("db-primary-delhi", true, null);
        List<Node> replicas = List.of(
            new Node("replica-delhi", false, "db-primary-delhi"),
            new Node("replica-mumbai", false, "replica-delhi"));   // cascading
        TopologyRouter router = new TopologyRouter(primary, replicas);
        router.routeWrite();          // SAV2001 balance update
        router.routeRead();           // report read
        router.routeRead();           // cascaded read
        router.detectConflict(5, 5);  // simulate active-active clash
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
